class ProfileState {
  const ProfileState({this.isLoading = false, this.error, this.user});
  final bool isLoading;
  final String? error;
  final User? user;
}

Widget buildProfile(ProfileState s) {
  if (s.isLoading) return const CircularProgressIndicator();
  if (s.error != null) return Text(s.error!);
  return Text(s.user!.name); // nothing stops user from being null here
}

sealed class ProfileState {
  const ProfileState();
}

final class ProfileLoading extends ProfileState {
  const ProfileLoading();
}

final class ProfileLoaded extends ProfileState {
  const ProfileLoaded(this.user);
  final User user;
}

final class ProfileFailed extends ProfileState {
  const ProfileFailed(this.message);
  final String message;
}

Widget buildProfile(ProfileState s) => switch (s) {
      ProfileLoading() => const CircularProgressIndicator(),
      ProfileLoaded(:final user) => Text(user.name),
      ProfileFailed(:final message) => Text(message),
    };
